// ============================================================================
// OBI_apb: APB4 register wrapper around OBI_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/OBI.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/OBI.md
// ============================================================================
module OBI_apb #(
  parameter int NOUT = 4,
  parameter int IDW = 4,
  parameter logic [9:0] PROT_BASE = 10'h300
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic req,
  output logic gnt,
  input logic [31:0] addr,
  input logic we,
  input logic [3:0] be,
  input logic [31:0] wdata,
  input logic [IDW-1:0] aid,
  input logic [2:0] prot,
  input logic [5:0] atop,
  input logic reqpar,
  output logic gntpar,
  output logic rvalid,
  input logic rready,
  output logic [31:0] rdata,
  output logic err,
  output logic [IDW-1:0] rid,
  output logic rvalidpar,
  input logic rreadypar
);
  localparam logic [31:0] ID_VALUE = 32'h4F420100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq_dec;
  logic          c_irq_prot;
  logic          c_irq_atop;
  logic          c_irq_par;
  OBI_top #(.NOUT(NOUT), .IDW(IDW), .PROT_BASE(PROT_BASE)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .req(req),
    .gnt(gnt),
    .addr(addr),
    .we(we),
    .be(be),
    .wdata(wdata),
    .aid(aid),
    .prot(prot),
    .atop(atop),
    .reqpar(reqpar),
    .gntpar(gntpar),
    .rvalid(rvalid),
    .rready(rready),
    .rdata(rdata),
    .err(err),
    .rid(rid),
    .rvalidpar(rvalidpar),
    .rreadypar(rreadypar),
    .irq_dec(c_irq_dec),
    .irq_prot(c_irq_prot),
    .irq_atop(c_irq_atop),
    .irq_par(c_irq_par)
  );

  // ---------------- registers ----------------
  logic [3:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[3:0] & wmask[3:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq_dec;
    irq_set[1] = c_irq_prot;
    irq_set[2] = c_irq_atop;
    irq_set[3] = c_irq_par;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
